// Guided browser adapter loaded after the legacy adapter.
analyze=function(img){const result=FlowerImage.analyze(img,ENGINE_PROFILES,{minimumScore:Number($('scoreThreshold').value),minimumLead:Number($('marginThreshold').value)}),out=result.out,w=result.canvas.width,h=result.canvas.height;if(typeof LeafView!=='undefined')LeafView.render(result);canvas.width=w;canvas.height=h;ctx.drawImage(result.canvas,0,0);for(const [name,id] of [['flower','maskPreview'],['centre','centreMaskPreview'],['rays','rayMaskPreview']]){const c=$(id);c.width=w;c.height=h;const cctx=c.getContext('2d'),pixels=cctx.createImageData(w,h),source=ctx.getImageData(0,0,w,h).data;for(let p=0;p<w*h;p++){const visible=out.masks[name][p];pixels.data.set(visible?[source[p*4],source[p*4+1],source[p*4+2],255]:[18,18,18,255],p*4)}cctx.putImageData(pixels,0,0)}$('centreMaskPreview').nextElementSibling.textContent=out.head_structure.status==='unknown'?'03 CENTRE · NOT RESOLVED':'03 CENTRE · PROPOSAL';$('rayMaskPreview').nextElementSibling.textContent=out.head_structure.status==='unknown'?'04 OUTER RAYS · NOT RESOLVED':'04 OUTER RAYS · PROPOSAL';const pc=$('petalPreview');pc.width=w;pc.height=h;const px=pc.getContext('2d');px.drawImage(result.canvas,0,0,w,h);const overlay=px.createImageData(w,h);for(let p=0;p<w*h;p++){const label=out.petals.labels[p];if(label)overlay.data.set(label%2?[255,255,255,100]:[0,0,0,110],p*4);}const oc=document.createElement('canvas');oc.width=w;oc.height=h;oc.getContext('2d').putImageData(overlay,0,0);px.drawImage(oc,0,0);px.font='bold 12px sans-serif';px.textAlign='center';px.textBaseline='middle';for(const r of out.petals.regions){px.fillStyle='#fff';px.beginPath();px.arc(r.x,r.y,9,0,Math.PI*2);px.fill();px.strokeStyle='#000';px.stroke();px.fillStyle='#000';px.fillText(String(r.label),r.x,r.y);}pc.nextElementSibling.textContent=out.petals.status==='unresolved'?'05 PETAL REGIONS · UNRESOLVED':'05 NUMBERED REGION CANDIDATES';const ec=$('edgePreview');ec.width=w;ec.height=h;const ex=ec.getContext('2d'),ei=ex.createImageData(w,h);for(let p=0;p<w*h;p++){const v=out.petals.boundary[p]?255:out.petals.edges[p]?140:18;ei.data.set([v,v,v,255],p*4);}ex.putImageData(ei,0,0);ec.nextElementSibling.textContent=out.petals.edge_diagnostics.used_for_count?'06 EDGES · WHITE CUT HYPOTHESES':'06 EDGES · GREY SIGNAL / WHITE HYPOTHESES';if(out.morphology){delete out.morphology.edges;for(const method of out.morphology.methods)delete method.labels;}delete out.petals.edges;delete out.petals.boundary;delete out.petals.labels;if(out.leaf){delete out.leaf.mask;delete out.leaf.labels;}delete out.masks;return out};
render=function(out){lastOutput=out;const top=out.candidates[0],usable=out.quality.usable;$('prediction').textContent=usable?(out.decision.lead<.001?'AMBIGUOUS':top.name):'NO RELIABLE REGION';$('latin').textContent=usable&&out.decision.lead>=.001?top.latin:'—';$('growthStage').textContent='Unknown'+(usable?' · hypothesis: '+top.stage:'');$('plantPart').textContent=usable?top.part:'—';$('petalCount').textContent=out.petals.visible_region_count==null?'Unresolved':String(out.petals.visible_region_count);$('petalCountNote').textContent=out.petals.visible_region_count==null?out.petals.reason:'Numbered region candidates; anatomical petal count unverified';$('decision').textContent='REVIEW REQUIRED';$('topScore').textContent=top.score.toFixed(3);$('leadScore').textContent=out.decision.lead.toFixed(3);$('runStatus').textContent='AUTOMATIC · EXPERIMENTAL';$('runStatus').className='status idle';$('decisionLog').textContent=(out.quality.issues.length?out.quality.issues.join('. ')+'. ':'')+out.decision.reason;const morphology=out.features.morphology;const obs=out.observations;
 const escape=value=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
 const valueOf=o=>o.value==null?'Unresolved':String(o.value).replaceAll('_',' ');
 const card=(title,body)=>`<section class="feature-group botanical-card"><h3>${title}</h3>${body}</section>`;
 const line=(label,o)=>`<p><strong>${label}</strong><br><span class="observation-value">${escape(valueOf(o))}</span><br><small>${escape(o.reason)}</small></p>`;
 const evidence=o=>o.evidence.length?`<small class="evidence-note">Evidence: ${o.evidence.map(e=>e.region?`numbered region ${e.region}`:e.view==='centreMaskPreview'?'centre overlay':'outer-ray overlay').join(', ')}</small>`:'';
 const cards=card('PETAL SHAPE',line('Region shape',obs.petalShape)+line('Individual tip',obs.petalTip)+evidence(obs.petalShape))+
 card('COUNT',line('Visible regions',obs.visibleCount)+`<small>Total petals: unverified. Hidden petals are not inferred.</small>`+evidence(obs.visibleCount))+
 card('ARRANGEMENT',line('Whorls / layers',obs.arrangement))+
 card('CENTRE',line('Visible structure',obs.centre)+evidence(obs.centre))+
 card('LEAF SUPPORT',typeof LeafView==='undefined'?line('Shape / attachment',obs.leafSupport):LeafView.summary(out.leaf));
 const categories={COLOUR:['pink','red','yellow','blue','pale'],OUTLINE:['circularity','solidity','aspect_ratio','symmetry'],OUTLINE_PEAKS:['visible_tips_low','visible_tips_high','tip_stability'],CENTRE:['center_yellow','outer_yellow','centre_contrast'],CONTEXT:['vegetation_coverage','vegetation_below']};
 if(out.head_structure.status!=='unknown')categories.HEAD_STRUCTURE=['ray_enclosure','disc_contrast','disc_fraction'];
 const diagnostics=Object.entries(categories).map(([title,keys])=>card(title,keys.map(key=>{const value=out.features[key];return `<div class="feature-item"><div class="feature-label"><span>${key.replaceAll('_',' ')}</span><strong>${value==null?'N/A':value.toFixed(3)}</strong></div><div class="bar"><span style="width:${Math.min(100,(value||0)*100)}%"></span></div></div>`}).join(''))).join('');
 $('featureRows').innerHTML=cards+`<details class="feature-diagnostics"><summary>Numerical diagnostics · colour, outline and edge measurements</summary><div class="diagnostic-grid">${diagnostics}${card('INTERNAL EDGES',`<p>Method: ${escape(out.petals.method.replaceAll('_',' '))}</p><p>Boundary hypotheses: ${out.petals.edge_diagnostics.boundary_count??'Unresolved'}</p><p>Edge threshold: ${out.petals.edge_diagnostics.threshold.toFixed(3)}</p>`)}</div></details>`;
 document.querySelector('.candidates thead').innerHTML='<tr><th>#</th><th>Candidate / stage hypothesis</th><th>Colour</th><th>Shape</th><th>Centre</th><th>Surface</th><th>Leaf fit / adjustment</th><th>Evidence coverage</th><th>Match strength</th></tr>';$('candidateRows').innerHTML=out.candidates.map(row=>`<tr><td>${row.rank}</td><td>${row.name}<br><small>${row.stage} · ${row.taxonRank}</small></td>${['colour','shape','centre','surface'].map(k=>`<td>${row.parts[k]==null?'—':row.parts[k].toFixed(2)}</td>`).join('')}<td>${row.leaf_evidence?.score==null?'—':row.leaf_evidence.score.toFixed(2)} / ${row.leaf_adjustment?.toFixed(3)||'0.000'}</td><td>${Math.round(row.coverage*100)}%<br><small>${escape(row.missing_required.length?'Missing: '+row.missing_required.join(', ').replaceAll('_',' '):row.evidence_status.replaceAll('_',' '))}</small></td><td>${row.score.toFixed(3)}</td></tr>`).join('');const strengths=top.evidence.filter(e=>!e.contradiction&&!e.unknown),conflicts=top.evidence.filter(e=>e.contradiction);$('rawOutput').textContent=`CANDIDATE EVIDENCE — ${top.name}\nShape labels describe the selected silhouette. Profile expectations are provisional, not botanical proof.\n\nMATCHED\n${strengths.map(e=>`${e.feature}: ${typeof e.value==='number'?e.value.toFixed(3):e.value} in [${e.expected.join(', ')}]`).join('\n')}\n\nCONFLICTS\n${conflicts.map(e=>`${e.feature}: ${typeof e.value==='number'?e.value.toFixed(3):e.value} outside [${e.expected.join(', ')}]`).join('\n')||'None among measured features'}\n\nSTRUCTURE\n${morphology.outline.value.replaceAll('_',' ')} outline; ${morphology.tips.value} outline tips. Petal tips remain unmeasured. Visible outline-peak estimate ${Math.round((out.features.visible_tips_low||0)*20)}–${Math.round((out.features.visible_tips_high||0)*20)} (uncertain when petals overlap).\n\nUNMEASURED\nFlower tubes, bracts, reproductive column, verified leaf arrangement.\n\nRAW OUTPUT\n${JSON.stringify(out,null,2)}`;$('copyButton').disabled=false;};
document.querySelector('.candidates .panel-head h2').textContent='EXPERIMENTAL CANDIDATES';document.querySelector('.candidates .panel-head span').textContent='uncalibrated match strength, not probability';document.querySelector('.raw h2').textContent='EVIDENCE / RAW OUTPUT';document.querySelector('.features .panel-head span').textContent='observations first · unresolved is not absent';
